"""The thirds UF template for the Lean bank check (lane C1L): generated by C1's checker (Theorem C template, prefix
truncation n chosen from the target by `choose_n`, zero tail), certificates searched over the Lean catalogue
`tableT ++ [LP1, LP2, R, S] ++ windows` by the exact mirror, re-verified in the Lean form, and emitted as
Bank/ThirdsContent/AutoUFData.lean (data + decide).  Constants: P_bad = 5, c_Fr <= 25, depth 64, C = 10^12.
`choose_n`: the smallest n with mu(n) = ct/(Dt - Lambda_fin(n)) <= target - slack/2, where slack = target - mu at
the exact Lambda (Bank/Thirds/Numerics: LamT, DtT, ctT; target 952671/100000); mu(n) decreases in n.
Usage: python -I -X utf8 emit_thirds_uf.py"""
import sys, math
from fractions import Fraction as F
from pathlib import Path
sys.dont_write_bytecode = True
HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
C1 = HERE.parents[3].parents[1] / 'outputs/Compatibility programme/automatic-banks-2026-10-28/C1'
sys.path.insert(1, str(C1))
import mirror as X
import gen_thirds_check as G
import emit_thirds as E
import checker as CK
import emit_bank_uf as EB

OUT = G.WORK / 'CatalanCore/Uniform/Bank/ThirdsContent/AutoUFData.lean'
CBIG = F(10) ** 12
NL = chr(10)
DT = F(251820307144120719543, 62500000000000000000)
CT = F(34136273513123893, 5000000000000000)
TARGET = F(95133, 10000)
B = dict(q=3, M=6, members=[1, 2], Pbad=5, cF=25, alpha0=F(23, 10), alpha0b=F(23, 10), t0=F(3, 1000), n_min=50,
         D=DT, c=CT, lam_rat=F(7808344448571, 2379657280000), lam_log2=F(9, 200), target=TARGET, lp2w=True, pre_nmax=8)


def lam_fin(n):
    bk = CK.Bank('thirds', True)
    T = CK.generated_templates(bk, n, CBIG, P_bad=5)
    return sum(F(23, 10) * T[j][0] + sum(a * (t - s) + b * (t * t - s * s) / 2 for s, t, a, b, _ in T[j][1])
               for j in T) / len(T)


def mu(lam):
    return CT / (DT - lam)


def dec(x):
    from decimal import Decimal
    return Decimal(x.numerator) / Decimal(x.denominator)


def choose_n():
    return EB.choose_n('thirds', B)


def catalogue(wins):
    return EB.catalogue(wins, B)


def build(wins, n):
    names, cat = catalogue(wins)
    bk = CK.Bank('thirds', True)
    T = EB.templates_new('thirds', B, n, CBIG)
    q, al = 3, F(3, 20)
    D = dict(q=3, M=6, al=al, members=[1, 2], depth=64, cF=25, Pbad=5, alpha0=F(23, 10), tau=None,
             alpha0b=F(23, 10), t0=F(3, 1000), cat=cat, iD6=5, tmpls={})
    used = set()
    for j, (t1, pieces) in T.items():
        ka = F(j, q)
        rows = []
        for P in pieces:
            r = EB.fast_search(P, cat, names, q, al, ka, D['depth'], D['cF'], D['Pbad'])
            assert r is not None, ('no certificate', j, P[:4])
            _, cert, _ = r
            used.add(names[cert[0]])
            for _, y, _ in cert[2]:
                used.add(names[y])
            rows.append((P, cert))
        D['tmpls'][j] = (t1, rows)
    D['tau'] = max(D['tmpls'][j][1][-1][0][1] for j in D['tmpls'])
    D['Lam'] = sum(X.mass(D['alpha0'], *D['tmpls'][j]) for j in D['tmpls']) / len(D['tmpls'])
    return D, names, used


HEADER = '''import CatalanCore.Uniform.Content.BankShared.Check.Bank
import CatalanCore.Uniform.Content.BankShared.Check.Prefix
import CatalanCore.Uniform.Content.BankShared.Check.Test
set_option Elab.async false
set_option maxRecDepth 100000

/-! # Data: the thirds UF template for the bank check (lane C1L)

Generated by `scripts/claude/bank/check/emit_thirds_uf.py`: C1's Theorem C template for thirds with UF (prefix
truncation `n = {N}` chosen from the target μ ≤ 952671/100000, the maximal affine runs of the profile minimum, the zero tail), certificates over the catalogue
`tableT ++ [LP1, LP2w, R, S] ++ windows ++ prefixes`, verified by the exact mirror.  `P_bad = 5`, `c_Fr ≤ 25`, depth `≤ 64`,
`C = 10¹²`.  `uf_check : check ufData = true`, one `decide +kernel` per chunk. -/

namespace CatalanCore.Uniform.Bank.ThirdsContent.AutoUF
open CatalanCore.Uniform.Content.BankShared.Check

/-- `n / d`. -/
abbrev qq (n : ℤ) (d : ℕ) : ℚ := Test.qq n d
'''


def lpiece(P):
    s, t, a, b, Cc = P
    return '⟨%s, %s, %s, %s, %s⟩' % tuple(E.lq(x) for x in (s, t, a, b, Cc))


def emit(D, T, wins, chunk=40):
    L = [HEADER.replace('{N}', str(D['n']))]
    pres = X.pres_list(B['pre_nmax'])
    L.append(NL.join([
        '/-- The M3D windows of the catalogue. -/',
        f'def ufWins : List (ℕ × ℕ) := {[tuple(w) for w in wins]}',
        '',
        f'/-- The prefix branches `brPre n j0 j1` (`1 ≤ n ≤ {B["pre_nmax"]}`, `j0 < 2`, `j1 < 3`). -/',
        f'def ufPres : List (ℕ × ℕ × ℕ) := {[tuple(x) for x in pres]}',
        '',
        '/-- LP1, LP2w, the rank branch, the UF branch (indices 6-9), the M3D windows, then the prefix branches. -/',
        'def ufExtra : List Branch :=',
        '  ([brLP1, brLP2w, brRank, brS] ++ ufWins.map (fun w => brWin w.1 w.2)) ++',
        '    ufPres.map (fun x => brPre x.1 x.2.1 x.2.2)', '']))
    names = {}
    for j in sorted(T):
        rows = T[j][1]
        names[j] = []
        for ci in range(0, len(rows), chunk):
            nm = f'u{j}_{ci // chunk}'
            names[j].append(nm)
            body = ',\n  '.join('(%s, %s)' % (lpiece(P), E.lcert(c)) for P, c in rows[ci:ci + chunk])
            L.append(f'def {nm} : List (QPiece × Cert) := [\n  {body}]\n')
        t1 = T[j][0]
        L.append(f'def ufT{j} : QTmpl := ⟨qq {t1.numerator} {t1.denominator}, {E.nest(names[j])}⟩\n')
    Lam, tau = D['Lam'], D['tau']
    L.append(f'''/-- The thirds UF bank data, with its finite `Λ_fin`. -/
def ufData : BankData where
  q := 3
  M := 6
  α := qq 3 20
  members := [1, 2]
  depth := 64
  cF := 25
  Pbad := 5
  α0 := qq 23 10
  τ := qq {tau.numerator} {tau.denominator}
  Λ := qq {Lam.numerator} {Lam.denominator}
  α0b := qq 23 10
  t0 := qq 3 1000
  extra := ufExtra
  tmpls := [{', '.join(f'({j}, ufT{j})' for j in sorted(T))}]
''')
    L.append(NL.join([
        '/-- The catalogue of `ufData` in the shape of `catValid_bankUFwP`. -/',
        'theorem ufData_cat : ufData.cat = tableT ++ ([brLP1, brLP2w, brRank, brS] ++',
        '    ufWins.map (fun w => brWin w.1 w.2)) ++ ufPres.map (fun x => brPre x.1 x.2.1 x.2.2) :=',
        '  (List.append_assoc _ _ _).symm', '']))
    for j in sorted(T):
        for nm in names[j]:
            L.append(f'set_option profiler true in\ntheorem {nm}_ok : pieceAll ufData {j} {nm} = true := by decide +kernel\n')
        L.append(f'set_option profiler true in\ntheorem ufT{j}_head : tmplHead ufData {j} ufT{j} = true := by decide +kernel\n')
        oks = ', '.join(f'{nm}_ok' for nm in names[j])
        L.append(f'''theorem ufT{j}_ok : tmplOK ufData {j} ufT{j} = true := by
  unfold tmplOK
  rw [ufT{j}_head]
  show (true && pieceAll ufData {j} ({E.nest(names[j])})) = true
  simp only [pieceAll_append, {oks}, Bool.and_self]
''')
    tl = ', '.join(f'({j}, ufT{j})' for j in sorted(T))
    oks = ', '.join(f'ufT{j}_ok' for j in sorted(T))
    L.append(f'''set_option profiler true in
theorem uf_params : checkParams ufData = true := by decide +kernel

set_option profiler true in
theorem uf_classes : ufData.members.all (classOK ufData) = true := by decide +kernel

theorem uf_tmpls : ufData.tmpls.all (fun x => tmplOK ufData x.1 x.2) = true := by
  show [{tl}].all (fun x => tmplOK ufData x.1 x.2) = true
  simp only [List.all_cons, List.all_nil, {oks}, Bool.and_self]

/-- **The bank check accepts the thirds UF data.** -/
theorem uf_check : check ufData = true := by
  unfold check
  rw [uf_params, uf_tmpls, uf_classes]
  rfl

end CatalanCore.Uniform.Bank.ThirdsContent.AutoUF
''')
    OUT.write_text('\n'.join(L), encoding='utf-8')


if __name__ == '__main__':
    n, mu_ex, slack = choose_n()
    print('n', n, 'mu at the exact Lambda', mu_ex, 'slack', slack)
    D, names, used = build(G.WINDOWS, n)
    wins = sorted({tuple(map(int, w[1:].split('_'))) for w in used if w.startswith('W')})
    D, names, used = build(wins, n)
    D['n'] = n
    ok, st = X.check(D)
    assert ok, 'mirror check rejected'
    T = E.lean_form(D)
    E.unit_check(D, T)
    emit(D, T, wins)
    cnt = {n: 0 for n in names}
    for j in D['tmpls']:
        for _, c in D['tmpls'][j][1]:
            cnt[names[c[0]]] += 1
    print('windows', wins)
    print('pieces', {j: len(D['tmpls'][j][1]) for j in D['tmpls']}, 'tau', D['tau'])
    print('branch usage', {k: v for k, v in cnt.items() if v})
    print('max R_P', float(st['max_R_P']), 'max C_needed', float(st['max_C_needed']))
    print('Lam_fin', D['Lam'], float(D['Lam']))
    print('mu(Lam_fin)', float(mu(D['Lam'])), '<= target', mu(D['Lam']) <= TARGET, 'excess over exact', float(dec(mu(D['Lam'])) - mu_ex))
    print('wrote', OUT)
